          <div className="logo-wrapper">
            <span className="logo-icon">🗑️</span>
          </div>
          <h1 className="title">Gestion Municipale des Déchets</h1>
          <p className="subtitle">Système intelligent de collecte et de suivi</p>
        </div>

        {/* Login Card */}
        <div className="login-card">
          {/* Card Header */}
          <div className="card-header">
            <h2 className="card-title">Connexion au système</h2>
            <p className="card-subtitle">Accédez à votre espace personnel</p>
          </div>

          {/* Card Body */}
          <div className="card-body">
            {error && (
              <div className="error-message">
                <div className="error-icon">⚠️</div>
                <div className="error-content">
                  <p className="error-text">{error}</p>
                </div>
              </div>
            )}

            <form onSubmit={handleSubmit} className="login-form">
              {/* Username Field */}
              <div className="form-group">
                <label htmlFor="username" className="form-label">
                  Nom d'utilisateur
                </label>
                <div className="input-wrapper">
                  <div className="input-icon">👤</div>
                  <input
                    id="username"
                    name="username"
                    type="text"
                    required
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="form-input"
                    placeholder="admin"
                    autoComplete="username"
                  />
                </div>
              </div>

              {/* Password Field */}
              <div className="form-group">
                <label htmlFor="password" className="form-label">
                  Mot de passe
                </label>
                <div className="input-wrapper">
                  <div className="input-icon">🔒</div>
                  <input
                    id="password"
                    name="password"
                    type="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="form-input"
                    placeholder="••••••••"
                    autoComplete="current-password"
                  />
                </div>
              </div>

              {/* Options */}
              <div className="form-options">
                <div className="remember-me">
                  <input
                    id="remember-me"
                    name="remember-me"
                    type="checkbox"
                    className="checkbox"
                  />
                  <label htmlFor="remember-me" className="checkbox-label">
